import { v } from "convex/values";
import { internalMutation } from "./_generated/server";

const HOUR_MS = 60 * 60 * 1000;
const DAY_MS = 24 * HOUR_MS;
const RETENTION_MS = 2 * DAY_MS;

// Device ids are generated by the app per install, so they are spoofable. The
// per-device windows stop casual abuse; the global window is the real cost
// ceiling until lookups require an account and spend credits.
const DEFAULT_DEVICE_HOURLY_LIMIT = 20;
const DEFAULT_DEVICE_DAILY_LIMIT = 60;
const DEFAULT_GLOBAL_DAILY_LIMIT = 1000;

export type LookupQuotaDecision =
  | { allowed: true }
  | { allowed: false; scope: "device" | "global"; retryAfterMs: number };

export const consumeLookupQuota = internalMutation({
  args: {
    deviceId: v.string(),
  },
  handler: async (ctx, args): Promise<LookupQuotaDecision> => {
    const now = Date.now();
    const windows = [
      {
        bucketKey: `device:${args.deviceId}:hour`,
        scope: "device" as const,
        sizeMs: HOUR_MS,
        limit: readLimit("PRICING_DEVICE_HOURLY_LIMIT", DEFAULT_DEVICE_HOURLY_LIMIT),
      },
      {
        bucketKey: `device:${args.deviceId}:day`,
        scope: "device" as const,
        sizeMs: DAY_MS,
        limit: readLimit("PRICING_DEVICE_DAILY_LIMIT", DEFAULT_DEVICE_DAILY_LIMIT),
      },
      {
        bucketKey: "global:day",
        scope: "global" as const,
        sizeMs: DAY_MS,
        limit: readLimit("PRICING_GLOBAL_DAILY_LIMIT", DEFAULT_GLOBAL_DAILY_LIMIT),
      },
    ];

    const counters = await Promise.all(
      windows.map(async (window) => {
        const windowStart = Math.floor(now / window.sizeMs) * window.sizeMs;
        const row = await ctx.db
          .query("lookupRateLimits")
          .withIndex("by_bucket", (q) => q.eq("bucketKey", window.bucketKey).eq("windowStart", windowStart))
          .unique();
        return { window, windowStart, row };
      }),
    );

    const exhausted = counters.find(({ window, row }) => (row?.count ?? 0) >= window.limit);
    if (exhausted) {
      return {
        allowed: false,
        scope: exhausted.window.scope,
        retryAfterMs: exhausted.windowStart + exhausted.window.sizeMs - now,
      };
    }

    for (const { window, windowStart, row } of counters) {
      if (row) {
        await ctx.db.patch(row._id, { count: row.count + 1 });
      } else {
        await ctx.db.insert("lookupRateLimits", { bucketKey: window.bucketKey, windowStart, count: 1 });
      }
    }

    return { allowed: true };
  },
});

export const pruneExpiredWindows = internalMutation({
  args: {},
  handler: async (ctx): Promise<number> => {
    const cutoff = Date.now() - RETENTION_MS;
    const expired = await ctx.db
      .query("lookupRateLimits")
      .withIndex("by_window_start", (q) => q.lt("windowStart", cutoff))
      .take(500);

    for (const row of expired) {
      await ctx.db.delete(row._id);
    }
    return expired.length;
  },
});

function readLimit(name: string, fallback: number): number {
  const parsed = Number(process.env[name]);
  return Number.isFinite(parsed) && parsed > 0 ? Math.floor(parsed) : fallback;
}
